import{_ as p,a0 as o,w as l,s as k,ao as n,I as s,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse(`{"title":"RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 12--Automate RHEL 7 Installations Using 'Kickstart'","title":"RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 12--Automate RHEL 7 Installations Using 'Kickstart'.md","filePath":"[post].md"}`),c={name:"RHCSA Series/RHCSA Series--Part 12--Automate RHEL 7 Installations Using 'Kickstart'.md"};function m(d,t,u,w,H,R){const r=o("Link");return l(),k("div",null,[t[18]||(t[18]=n('<h1 id="rhcsa-系列-十二-使用-kickstart-完成-rhel-7-的自動化安裝" tabindex="-1">RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝 <a class="header-anchor" href="#rhcsa-系列-十二-使用-kickstart-完成-rhel-7-的自動化安裝" aria-label="Permalink to “RHCSA 系列（十二）: 使用 Kickstart 完成 RHEL 7 的自動化安裝”">​</a></h1><p>無論是在數據中心還是實驗室環境，Linux 服務器很少是獨立的機器，很可能有時你需要安裝多個以某種方式相互聯繫的機器。假如你將在單個服務器上手動安裝 RHEL 7 所花的時間乘以你需要配置的機器數量，這將導致你必須做出一場相當長的努力，而通過使用被稱為 kicksta 的無人值守安裝工具則可以避免這樣的麻煩。</p><p>在這篇文章中，我們將向你展示使用 kickstart 工具時所需的一切，以便在安裝過程中，不用你時不時地照看“處在襁褓中”的服務器。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Automatic-Kickstart-Installation-of-RHEL-7.jpg" alt="RHEL 7 的自動化 Kickstart 安裝"></p><p><em>RHCSA： RHEL 7 的自動化 Kickstart 安裝</em></p><h4 id="kickstart-和自動化安裝簡介" tabindex="-1">Kickstart 和自動化安裝簡介 <a class="header-anchor" href="#kickstart-和自動化安裝簡介" aria-label="Permalink to “Kickstart 和自動化安裝簡介”">​</a></h4><p>Kickstart 是一種被用來執行無人值守操作系統安裝和配置的自動化安裝方法，主要被 RHEL（以及其他 Fedora 的副產品，如 CentOS，Oracle Linux 等）所使用。因此，kickstart 安裝方法可使得系統管理員只需考慮需要安裝的軟件包組和系統的配置，便可以得到相同的系統，從而省去必須手動安裝這些軟件包的麻煩。</p><h3 id="準備-kickstart-安裝" tabindex="-1">準備 Kickstart 安裝 <a class="header-anchor" href="#準備-kickstart-安裝" aria-label="Permalink to “準備 Kickstart 安裝”">​</a></h3><p>要執行 kickstart 安裝，我們需要遵循下面的這些步驟：</p><ol><li><p>創建一個 Kickstart 文件，它是一個帶有多個預定義配置選項的純文本文件。</p></li><li><p>將 Kickstart 文件保存在可移動介質上，如一個硬盤或一個網絡位置。kickstart 客户端需要使用 <code>rhel-server-7.0-x86_64-boot.iso</code> 鏡像文件，而你還需要可從一個網絡資源上獲取得到完整的 ISO 鏡像 <code>rhel-server-7.0-x86_64-dvd.iso</code> ，例如通過一個 FTP 服務器的 HTTP 服務形式（在我們當前的例子中，我們將使用另一個 IP 地址為 192.168.0.18 的 RHEL 7 機器）。</p></li><li><p>開始 Kickstart 安裝。</p></li></ol>',10)),s("p",null,[t[1]||(t[1]=a("要創建一個 kickstart 文件，請登錄你的紅帽客户門户網站（Red Hat Customer Portal）帳户，並使用 ",-1)),e(r,{href:"https://access.redhat.com/labs/kickstartconfig/"},{default:i(()=>[...t[0]||(t[0]=[a("Kickstart 配置工具",-1)])]),_:1}),t[2]||(t[2]=a(" 來選擇所需的安裝選項。在向下滑動之前請仔細閲讀每個選項，然後選擇最適合你需求的選項：",-1))]),t[19]||(t[19]=n(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Kickstart-Configuration-Tool.png" alt="Kickstart 配置工具"></p><p><em>Kickstart 配置工具</em></p><p>假如你指定安裝將通過 HTTP，FTP，NFS 來執行，請確保服務器上的防火牆允許這些服務通過。</p><p>儘管你可以使用紅帽的在線工具來創建一個 kickstart 文件，但你還可以使用下面的代碼來作為參考手動地創建它。例如，你可以注意到，下面的代碼指定了安裝過程將使用英語環境，使用拉丁美洲鍵盤佈局，並設定時區為 America/Argentina/San_Luis 時區：</p><pre><code>lang en_US
keyboard la-latin1
timezone America/Argentina/San_Luis --isUtc
rootpw $1$5sOtDvRo$In4KTmX7OmcOW9HUvWtfn0 --iscrypted
#platform x86, AMD64, or Intel EM64T
text
url --url=http://192.168.0.18//kickstart/media
bootloader --location=mbr --append=&quot;rhgb quiet crashkernel=auto&quot;
zerombr
clearpart --all --initlabel
autopart
auth --passalgo=sha512 --useshadow
selinux --enforcing
firewall --enabled
firstboot --disable
%packages
@base
@backup-server
@print-server
%end
</code></pre><p>在上面的在線配置工具中，在選擇以 HTTP 來作為安裝源後，設置好在安裝過程中使用 192.168.0.18 來作為 HTTP 服務器的地址，<code>/kickstart/tecmint.bin</code> 作為 HTTP 目錄。</p><p>在上面的 kickstart 示例文件中，你需要特別注意</p><pre><code>url --url=http://192.168.0.18//kickstart/media
</code></pre><p>這個目錄是你展開 DVD 或 ISO 安裝介質內容的地方。在執行解壓之前，我們將把 ISO 安裝文件作為一個迴環設備掛載到 /media/rhel 目錄下：</p><pre><code># mount -o loop /var/www/html/kickstart/rhel-server-7.0-x86_64-dvd.iso /media/rhel
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Mount-RHEL-ISO-Image.png" alt="掛載 RHEL ISO 鏡像"></p><p><em>掛載 RHEL ISO 鏡像</em></p><p>接下來，複製 /media/rhel 中的全部文件到 /var/www/html/kickstart/media 目錄：</p><pre><code># cp -R /media/rhel /var/www/html/kickstart/media
</code></pre><p>這一步做完後，/var/www/html/kickstart/media 目錄中的文件列表和磁盤使用情況將如下所示：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Kickstart-media-Files.png" alt="Kickstart 媒體文件"></p><p><em>Kickstart 媒體文件</em></p><p>現在，我們已經準備好開始 kickstart 安裝了。</p><p>不管你如何選擇創建 kickstart 文件的方式，在執行安裝之前檢查下這個文件的語法是否有誤總是一個不錯的主意。為此，我們需要安裝 pykickstart 軟件包。</p><pre><code># yum update &amp;&amp; yum install pykickstart
</code></pre><p>然後使用 ksvalidator 工具來檢查這個文件：</p><pre><code># ksvalidator /var/www/html/kickstart/tecmint.bin
</code></pre><p>假如文件中的語法正確，你將不會得到任何輸出，反之，假如文件中存在錯誤，你得到警告，向你提示在某一行中語法不正確或出錯原因未知。</p><h3 id="執行-kickstart-安裝" tabindex="-1">執行 Kickstart 安裝 <a class="header-anchor" href="#執行-kickstart-安裝" aria-label="Permalink to “執行 Kickstart 安裝”">​</a></h3><p>首先，使用 rhel-server-7.0-x86_64-boot.iso 來啓動你的客户端。當初始屏幕出現時，選擇安裝 RHEL 7.0 ，然後按 Tab 鍵來追加下面這一句，接着按 Enter 鍵：</p><pre><code># inst.ks=http://192.168.0.18/kickstart/tecmint.bin
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/RHEL-Kickstart-Installation.png" alt="RHEL Kickstart 安裝"></p><p><em>RHEL Kickstart 安裝</em></p><p>其中 tecmint.bin 是先前創建的 kickstart 文件。</p><p>當你按了 Enter 鍵後，自動安裝就開始了，且你將看到一個列有正在被安裝的軟件的列表（軟件包的數目和名稱根據你所選擇的程序和軟件包組而有所不同）：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Kickstart-Automatic-Installation.png" alt="RHEL 7 的自動化 Kickstart 安裝"></p><p><em>RHEL 7 的自動化 Kickstart 安裝</em></p><p>當自動化過程結束後，將提示你移除安裝介質，接着你就可以啓動到你新安裝的系統中了：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/RHEL-7.png" alt="RHEL 7 啓動屏幕"></p><p><em>RHEL 7 啓動屏幕</em></p><p>儘管你可以像我們前面提到的那樣，手動地創建你的 kickstart 文件，但你應該儘可能地考慮使用受推薦的方式：你可以使用在線配置工具，或者使用在安裝過程中創建的位於 root 家目錄下的 anaconda-ks.cfg 文件。</p><p>這個文件實際上就是一個 kickstart 文件，你或許想在選擇好所有所需的選項（可能需要更改邏輯卷佈局或機器上所用的文件系統）後手動地安裝第一個機器，接着使用產生的 anaconda-ks.cfg 文件來自動完成其餘機器的安裝過程。</p><p>另外，使用在線配置工具或 anaconda-ks.cfg 文件來引導將來的安裝將允許你在系統安裝時以加密的形式設置 root 密碼。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>既然你知道了如何創建 kickstart 文件並如何使用它們來自動完成 RHEL 7 服務器的安裝，你就可以不用時時照看安裝進度的過程了。這將給你時間來做其他的事情，或者若你足夠幸運，你還可以用來休閒一番。</p><p>無論以何種方式，請使用下面的評論欄來讓我們知曉你對這篇文章的看法。提問也同樣歡迎！</p>`,41)),s("p",null,[t[4]||(t[4]=a("另外，請閲讀：",-1)),e(r,{href:"http://www.tecmint.com/multiple-centos-installations-using-kickstart/"},{default:i(()=>[...t[3]||(t[3]=[a("使用 PXE 和 kickstart 來自動化安裝多個 RHEL/CentOS 7 發行版本",-1)])]),_:1})]),t[20]||(t[20]=s("hr",null,null,-1)),s("p",null,[t[6]||(t[6]=a("via: ",-1)),e(r,{href:"http://www.tecmint.com/automatic-rhel-installations-using-kickstart/"},{default:i(()=>[...t[5]||(t[5]=[a("http://www.tecmint.com/automatic-rhel-installations-using-kickstart/",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=a("作者：",-1)),e(r,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...t[7]||(t[7]=[a("Gabriel Cánepa",-1)])]),_:1}),t[11]||(t[11]=a(" 譯者：",-1)),e(r,{href:"https://github.com/FSSlc"},{default:i(()=>[...t[8]||(t[8]=[a("FSSlc",-1)])]),_:1}),t[12]||(t[12]=a(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...t[9]||(t[9]=[a("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=a("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[a("LCTT",-1)])]),_:1}),t[16]||(t[16]=a(" 原創翻譯，",-1)),e(r,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[a("Linux中國",-1)])]),_:1}),t[17]||(t[17]=a(" 榮譽推出",-1))])])}const T=p(c,[["render",m]]);export{L as __pageData,T as default};
